    "        <label>密码</label>\n"
    "        <input id=\"wifiPasswordInput\" type=\"password\" placeholder=\"开放网络可留空\">\n"
    "      </div>\n"
    "      <div class=\"modal-actions\">\n"
    "        <button class=\"button ghost\" onclick=\"closeWifiModal()\">取消</button>\n"
    "        <button id=\"connectWifiBtn\" class=\"button primary\" onclick=\"connectSelectedWifi()\">连接</button>\n"
    "      </div>\n"
    "    </div>\n"
    "  </div>\n"
    "  <script>\n"
    "    const sectionFields={model:[['provider','text'],['token_env','text'],['model','text'],['api_key','text'],['base_url','text'],['temperature','number'],['max_tokens','number']],tts:[['provider','text'],['api_key','text'],['model','text'],['voice_id','text'],['emotion','text'],['speed','number']],stt:[['provider','text'],['api_key','text'],['model','text'],['base_url','text'],['secret_id','text'],['secret_key','text'],['region','text'],['engine_model_type','text']],audio:[['socket','text'],['sample_rate','number'],['channels','number'],['bit_width','number']],hid:[['keyboard_device','text'],['mouse_device','text'],['frame_socket','text']],proxy:[['http_proxy','text'],['https_proxy','text'],['all_proxy','text'],['no_proxy','text']],search:[['provider','text'],['api_key','text']],agent:[['input_mode','text'],['trigger_mode','text'],['energy_threshold','number'],['silence_ms','number'],['min_speech_ms','number'],['max_iterations','number'],['instruction','text'],['additional_prompt','text']]};\n"
    "    const appState={config:null,wifi:null,wifiStatus:null,networks:[],selectedSsid:''};\n"
    "    const sectionSnapshots={};\n"
    "    function byId(id){return document.getElementById(id);}\n"
    "    function setBanner(message,isError){const el=byId('actionBanner');el.textContent=message;el.className='banner'+(isError?' error':'');}\n"
    "    function setDetails(text){const wrap=byId('actionDetails');const body=byId('actionDetailsText');if(text){wrap.style.display='block';body.textContent=text;}else{wrap.style.display='none';body.textContent='';}}\n"
    "    async function request(url,options){const res=await fetch(url,options);const text=await res.text();let body={};try{body=text?JSON.parse(text):{}}catch(err){body={ok:false,error:text||err.message}}if(!res.ok){throw new Error(body.error||('HTTP '+res.status))}return body;}\n"
    "    function setSectionLocked(section,locked){document.querySelectorAll('[data-section='+section+']').forEach(function(el){el.disabled=locked;});byId('save-'+section).disabled=locked;}\n"
    "    function lockAllSections(){Object.keys(sectionFields).forEach(function(section){setSectionLocked(section,true);byId('section-'+section).classList.remove('editing');});}\n"
    "    function enterEditSection(section){const snap={};sectionFields[section].forEach(function(item){snap[item[0]]=byId(section+'_'+item[0]).value;});sectionSnapshots[section]=snap;setSectionLocked(section,false);byId('section-'+section).classList.add('editing');setBanner('正在编辑 ['+section+']，改完后点保存。',false);setDetails('');}\n"
    "    function cancelEditSection(section){const snap=sectionSnapshots[section]||{};sectionFields[section].forEach(function(item){const el=byId(section+'_'+item[0]);if(snap[item[0]]!==undefined)el.value=snap[item[0]];});delete sectionSnapshots[section];setSectionLocked(section,true);byId('section-'+section).classList.remove('editing');setBanner('已取消 ['+section+'] 的修改。',false);setDetails('');}\n"
    "    function setFieldValue(section,key,value){const el=byId(section+'_'+key);if(!el)return;el.value=value==null?'':value;}\n"
    "    function fillConfigForm(config){Object.keys(sectionFields).forEach(function(section){const values=config[section]||{};sectionFields[section].forEach(function(item){setFieldValue(section,item[0],values[item[0]]);});});}\n"
    "    function readSection(section){const values={};sectionFields[section].forEach(function(item){const key=item[0];const type=item[1];const raw=byId(section+'_'+key).value;if(type==='number'){values[key]=raw===''?0:Number(raw);}else{values[key]=raw;}});return values;}\n"
    "    function renderWifiList(){const list=byId('wifiList');list.innerHTML='';if(!appState.networks.length){const empty=document.createElement('div');empty.className='wifi-row';const left=document.createElement('div');const title=document.createElement('div');title.className='wifi-main';title.textContent='未扫描到网络';const meta=document.createElement('div');meta.className='wifi-meta';meta.textContent='点“重新扫描”再试一次';left.appendChild(title);left.appendChild(meta);empty.appendChild(left);list.appendChild(empty);return;}appState.networks.forEach(function(name){const item=document.createElement('button');item.type='button';let cls='wifi-row';let metaText='';let state='';if(appState.wifiStatus&&appState.wifiStatus.connected&&appState.wifiStatus.ssid===name){cls+=' current';metaText=appState.wifiStatus.ip_address?('已连接 · '+appState.wifiStatus.ip_address):'已连接';state='✓';}else if(appState.wifi&&appState.wifi.ssid===name){cls+=' saved';metaText='已保存';}item.className=cls;item.onclick=function(){openWifiModal(name);};const left=document.createElement('div');const title=document.createElement('div');title.className='wifi-main';title.textContent=name;left.appendChild(title);if(metaText){const meta=document.createElement('div');meta.className='wifi-meta';meta.textContent=metaText;left.appendChild(meta);}const right=document.createElement('div');right.className='wifi-state';right.textContent=state;item.appendChild(left);item.appendChild(right);list.appendChild(item);});}\n"
    "    function applyPayload(payload){appState.config=payload.config||{};appState.wifi=payload.wifi||{};appState.wifiStatus=payload.wifi_status||{};fillConfigForm(appState.config);lockAllSections();}\n"
    "    async function loadConfig(){const payload=await request('/api/config',{method:'GET'});applyPayload(payload);if(payload.config_error||payload.wifi_error){setDetails([payload.config_error||'',payload.wifi_error||''].filter(Boolean).join('\\n'));}return payload;}\n"
    "    async function scanWifi(showBanner){byId('scanBtn').disabled=true;try{const payload=await request('/api/wifi/scan',{method:'POST'});appState.networks=payload.networks||[];renderWifiList();if(showBanner!==false){setBanner('Wi-Fi 列表已刷新。',false);setDetails('');}}catch(err){setBanner('扫描 Wi-Fi 失败。',true);setDetails(err.message);}finally{byId('scanBtn').disabled=false;}}\n"
    "    async function reloadAll(){byId('reloadBtn').disabled=true;try{await loadConfig();await scanWifi(false);setBanner('已刷新配置和 Wi-Fi 列表。',false);}catch(err){setBanner('刷新失败。',true);setDetails(err.message);}finally{byId('reloadBtn').disabled=false;}}\n"
    "    function openWifiModal(ssid){appState.selectedSsid=ssid;byId('wifiModalText').textContent='连接到 “'+ssid+'”';byId('wifiPasswordInput').value=(appState.wifi&&appState.wifi.ssid===ssid&&appState.wifi.psk)?appState.wifi.psk:'';byId('wifiModal').classList.add('show');byId('wifiPasswordInput').focus();}\n"
    "    function closeWifiModal(){byId('wifiModal').classList.remove('show');appState.selectedSsid='';}\n"
    "    async function connectSelectedWifi(){const ssid=appState.selectedSsid;const psk=byId('wifiPasswordInput').value;byId('connectWifiBtn').disabled=true;try{const payload=await request('/api/wifi/connect',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({ssid:ssid,psk:psk})});appState.wifi=payload.wifi||{ssid:ssid,psk:psk};appState.wifiStatus=payload.wifi_status||{};renderWifiList();closeWifiModal();setBanner('已尝试连接 “'+ssid+'”。',!payload.ok);setDetails(payload.wifi_apply&&payload.wifi_apply.output?payload.wifi_apply.output:'');}catch(err){setBanner('连接 Wi-Fi 失败。',true);setDetails(err.message);}finally{byId('connectWifiBtn').disabled=false;}}\n"
    "    async function saveSection(section){if(!appState.config){return;}byId('save-'+section).disabled=true;try{appState.config[section]=readSection(section);const payload=await request('/api/config',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({config:appState.config,apply_wifi:false})});if(payload.config){appState.config=payload.config;}fillConfigForm(appState.config);delete sectionSnapshots[section];setSectionLocked(section,true);byId('section-'+section).classList.remove('editing');setBanner('['+section+'] 已保存。',false);setDetails('');}catch(err){setBanner('保存 ['+section+'] 失败。',true);setDetails(err.message);setSectionLocked(section,false);}finally{byId('save-'+section).disabled=false;}}\n"
    "    window.addEventListener('click',function(event){if(event.target===byId('wifiModal')){closeWifiModal();}});\n"
    "    (async function init(){lockAllSections();setBanner('正在读取配置...',false);try{await loadConfig();await scanWifi(false);setBanner('请选择 Wi-Fi，或按分组编辑 agent.toml。',false);}catch(err){setBanner('页面初始化失败。',true);setDetails(err.message);}})();\n"
    "  </script>\n"
    "</body>\n"
    "</html>\n";
